  str_senior_skin_draw_cost_not_enough = "{1}數量不足",
  str_senior_skin_draw_duplicate_tip = "重複獎勵變更",
  str_senior_skin_draw_time_limit_review = "限時復刻",
  str_senior_skin_draw_duplicate_title = "重複獲得獎勵變更說明",
  str_senior_skin_draw_award_change_to = "獎勵變更為",
  str_senior_skin_draw_rule_title_blh = "綺色樂間 規則說明",
  str_senior_skin_draw_rule_detail_blh = "○許願必得<color=#d70500>1</color>份獎勵，首次許願不消耗筆記，後<color=#d70500>9</color>次許願需要消耗筆記。\n○活動共有<color=#d70500>10</color>份獎勵，每份獎勵只能獲取<color=#d70500>1</color>次，不會重複獲得。即每次許願所得內容將從獎勵內容中移除，不會作為後續許願的可獲取內容。<color=#d70500>10</color>次許願可得所有內容。\n○隨著許願次數的增加，所需消耗的筆記數量有所不同，第<color=#d70500>2</color>次至第<color=#d70500>10</color>次許願需分別消耗：<color=#d70500>1</color>、<color=#d70500>1</color>、<color=#d70500>2</color>、<color=#d70500>4</color>、<color=#d70500>6</color>、<color=#d70500>6</color>、<color=#d70500>10</color>、<color=#d70500>10</color>、<color=#d70500>10</color>個筆記。具體消耗可留意每次許願的按鈕顯示。\n○您可付費購買更多筆記。筆記為限時道具，<color=#063c8e>綺色樂間</color>活動結束後，未使用的筆記將自動轉化為<color=#d70500>100</color>光珀，請在活動結束<color=#d70500>1</color>小時後留意遊戲內系統郵件。",
  str_senior_skin_draw_rule_reward_detail_blh = "特典時裝<color=#063c8e>【綺色樂間】</color>有機會在第<color=#d70500>6</color>次及之後的許願中獲得，最多許願<color=#d70500>10</color>次，將必得這一特典時裝以及所有道具。\n\n完整獎勵內容如下——\n最高獎勵：伯利恆特典時裝<color=#063c8e>【綺色樂間】</color>*1，重複獲得獎勵變更為光珀*3,000\n稀有獎勵：光珀*<color=#d70500>600</color> + 限定空庭建築<color=#063c8e>【雪山沙發】</color>*1，重複獲得獎勵變更為光珀*600+特召星標*1\n稀有獎勵：光珀*<color=#d70500>600</color> + 限定頭像框<color=#063c8e>【天才的耳麥】</color>*1，重複獲得獎勵變更為光珀*600+特召星標*1\n稀有獎勵：光珀*<color=#d70500>600</color> + 限定頭像<color=#063c8e>【樂間中的伯利恆】</color>*1，重複獲得獎勵變更為光珀*600+特召星標*1\n高級獎勵：光珀*<color=#d70500>300</color> + <color=#063c8e>藍色特級訂購箱</color>*10\n高級獎勵：光珀*<color=#d70500>300</color> + <color=#063c8e>三階瑩玉訂購箱</color>*25\n高級獎勵：光珀*<color=#d70500>300</color> + <color=#063c8e>充能盒</color>*10\n中級獎勵：光珀*<color=#d70500>200</color> + <color=#063c8e>二階瑩玉訂購箱</color>*30\n中級獎勵：光珀*<color=#d70500>200</color> + <color=#063c8e>靈質</color>*1,000\n中級獎勵：光珀*<color=#d70500>200</color> +<color=#063c8e> 白夜幣</color>*200,000",
  str_senior_skin_draw_rule_reward_tips_title_blh = "機率說明：",
  str_senior_skin_draw_rule_reward_tips_blh = "下面列出的是許願中<color=#d70500>10</color>份獎品的基礎獲取機率。\n許願獲得某個獎品後，剩下的獎品機率會進行動態變化，以各獎品基礎獲取機率的比重來重新分配。（總機率仍為<color=#d70500>100%</color>）。<b><color=#302f2f>所有導航員參與活動的基礎獲取機率是相同的。</color></b><b><color=#302f2f>具體動態機率詳見主介面動態機率顯示按鈕。</color></b>",
